def day(d):return datetime.fromisoformat(d).strftime('%d/%m')
def copies(p):
 return f'''<div class="copy-grid">{''.join(f'<section class="copy-block"><div><h4>{platform}</h4><button type="button" class="copy-button" data-copy="{p['id']}-{key}">Copiar texto de {platform}</button></div><textarea readonly id="{p['id']}-{key}" aria-label="Copy para {platform}, {p['id']}">{e(p[key])}</textarea></section>' for platform,key in [('Facebook','fb'),('Instagram','ig')])}</div>'''
def asset(a):
 file=e(a['file']);label=e(a['label'])
 if a['type']=='video': return f'<div class="asset"><video controls playsinline preload="none" poster="{e(next(p["preview"] for p in data["posts"] if a["file"].split("/")[-1].startswith(p["id"])))}" aria-label="{label}"><source src="{file}" type="video/mp4"></video><a class="download" href="{file}" download>Descargar {label}</a></div>'
 if a['type']=='gif':return f'<div class="asset gif-asset"><p>GIF animado de vista previa. Para Reels y anuncios, usa el MP4.</p><details class="gif-preview"><summary>Reproducir el GIF</summary><img data-gif="{file}" alt="Explicación animada del proceso" width="540" height="675"></details><a class="download" href="{file}" download>Descargar {label}</a></div>'
 return f'<div class="asset"><a href="{file}" target="_blank" rel="noopener"><img src="{file}" loading="lazy" alt="{label}" width="216" height="270"></a><a class="download" href="{file}" download>Descargar {label}</a></div>'
def post(p):
 badges=(' <span class="badge launch">Lanzamiento</span>' if p['launch'] else '')+(' <span class="badge">Fijar</span>' if p['pinned'] else '')
