launch=''.join(f'<a href="#{id}"><span>{i+1}</span><div><strong>{id} · {e(next(p["title"] for p in data["posts"] if p["id"]==id))}</strong><small>{day(next(p["date"] for p in data["posts"] if p["id"]==id))} · {next(p["time"] for p in data["posts"] if p["id"]==id)} · Lima</small></div></a>' for i,id in enumerate(data['launchOrder']))
events=[dict(id=p['id'],date=p['date'],time=p['time'],title=p['title'],type=p['format'],anchor=p['id']) for p in data['posts']]+[dict(id=p['id'],date=p['date'],time=p['time'],title=p['title'],type='Historias · 3 JPG',anchor='historias-'+p['id']) for p in data['storyItems']]
events.sort(key=lambda p:(p['date'],p['time']))
