ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Nexo//Calendario de contenido//ES','CALSCALE:GREGORIAN','METHOD:PUBLISH']
for p in events:
 start=datetime.fromisoformat(p['date']+'T'+p['time'])+timedelta(hours=5);end=start+timedelta(minutes=30)
 # UTF-8 folding follows RFC 5545's octet limit, not Python character count.
 values=['BEGIN:VEVENT','UID:'+p['id']+'-202610-nexo@nexoamedida.com','DTSTAMP:20261019T120000Z','DTSTART:'+start.strftime('%Y%m%dT%H%M%SZ'),'DTEND:'+end.strftime('%Y%m%dT%H%M%SZ'),'SUMMARY:'+p['id']+' - '+p['title'].replace(',','\\,'),'DESCRIPTION:Publicación sugerida en Facebook e Instagram. Zona horaria original: Lima.','END:VEVENT']
 ics.extend(values)
ics.append('END:VCALENDAR')
